// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address baseToken, address nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        if (_feeRate > 5000) _feeRate = 5000;

        bool ok;
        try c.initialize(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, _changeFee, _fee_rate_cast(_feeRate), _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            uint56 stored = c.changeFee();
            assertTrue(stored == _changeFee, "stored changeFee must equal provided _changeFee");
        } else {
            assertTrue(!ok, "initialize reverted");
        }
    }

    function _fee_rate_cast(uint16 x) internal pure returns (uint16) { return x; }
}
